function Sheet4({ slots: { Digits, Q, R, Box, Tick, C } }: SheetProps) {
  return (<section className="sheet" data-sheet="4" aria-label="Induk SPT – halaman 2"><header className="induk-head"><div className="induk-id"><img src="/images/branding/kemenkeu-seal.webp" alt="Kementerian Keuangan" /><span>KEMENTERIAN KEUANGAN<br />REPUBLIK INDONESIA<br /><strong>DIREKTORAT JENDERAL PAJAK</strong></span></div><div className="induk-name">SPT TAHUNAN<br /><span style={{"fontSize":"8pt"}}>PAJAK PENGHASILAN (PPh)<br />WAJIB PAJAK ORANG PRIBADI</span></div><div className="induk-box"><strong>INDUK</strong><br />HALAMAN 2</div></header><div className="section" data-sec="E">E. PPh KURANG/LEBIH BAYAR</div><div className="form-body"><div className="line-row"><b>11</b><span style={{"minWidth":"0","flex":"1"}}>PPh KURANG/LEBIH BAYAR</span><span className="r-formula">( <i className="ref">9</i> - <i className="ref">10a</i> - <i className="ref">10b</i> - <i className="ref">10c</i> + <i className="ref">10d</i> )</span><R s={4} i={0} /></div><div className="question"><div className="nb"></div><div className="nb">b</div><div className="qtext">APAKAH TERDAPAT SURAT KEPUTUSAN PERSETUJUAN PENGANGSURAN ATAU PENUNDAAN PEMBAYARAN PAJAK?</div><Q s={4} i={0} /></div><div className="opts"><p><Tick s={4} i={0} />Tidak, saya tidak memilikinya. (Lanjut ke pertanyaan selanjutnya)</p><p><Tick s={4} i={1} />Ya, saya memilikinya. (Isi dengan jumlah yang telah disetujui untuk diangsur/ditunda, lalu ke pertanyaan selanjutnya)</p></div><div className="line-row"><b className="l">c</b><span style={{"minWidth":"0","flex":"1"}}>PPh YANG MASIH HARUS DIBAYAR</span><span className="r-formula">( <i className="ref">11a</i> - <i className="ref">11b</i> )</span><R s={4} i={1} /></div></div><div className="section" data-sec="F">F. PEMBETULAN (DIISI JIKA STATUS SPT ADALAH PEMBETULAN)</div><div className="form-body"><div className="line-row"><b>12</b><span style={{"minWidth":"0","flex":"1"}}>PPh KURANG/LEBIH BAYAR PADA SPT YANG DIBETULKAN</span><span className="gantispt"><span className="cbx"></span>GANTI SPT SEBELUMNYA</span><R s={4} i={2} /></div><div className="line-row"><b className="l">b</b><span style={{"minWidth":"0","flex":"1"}}>PPh KURANG/LEBIH BAYAR KARENA PEMBETULAN</span><span className="r-formula">( <i className="ref">11a</i> - <i className="ref">12a</i> )</span><R s={4} i={3} /></div></div><div className="section" data-sec="G">G. PERMOHONAN PENGEMBALIAN PPh LEBIH BAYAR (DIISI JIKA STATUS SPT ADALAH LEBIH BAYAR)</div><div className="form-body"><div className="line-row"><div style={{"flex":"1"}}>PPh LEBIH BAYAR PADA 11a ATAU 12b MOHON:<br /><Tick s={4} i={2} />Dikembalikan melalui pemeriksaan.<br /><Tick s={4} i={3} />Dikembalikan melalui permohonan pengembalian pendahuluan.</div><div style={{"flex":"1"}}>NOMOR REKENING &nbsp; <Box s={4} i={0} style={{"width":"37mm"}} /><br />NAMA BANK &nbsp; <Box s={4} i={1} style={{"width":"38mm"}} /><br />NAMA PEMILIK REKENING &nbsp; <Box s={4} i={2} style={{"width":"50mm"}} /></div></div></div><div className="section" data-sec="H">H. ANGSURAN PPh PASAL 25 TAHUN PAJAK BERIKUTNYA</div><div className="form-body"><div className="question"><div className="nb">13</div><div className="nb">a</div><div className="qtext">APAKAH ANDA HANYA MENERIMA PENGHASILAN TERATUR DAN BERKEWAJIBAN MEMBAYAR ANGSURAN PPh PASAL 25 TAHUN PAJAK BERIKUTNYA?</div><Q s={4} i={1} /></div><div className="opts"><p><Tick s={4} i={4} />Tidak. (Lanjut ke pertanyaan selanjutnya)</p><p><Tick s={4} i={5} />Ya, angsuran PPh Pasal 25-nya adalah <span className="inline-formula">(1/<span className="inbox"></span> x ( <i className="ref">9</i> - <i className="ref">10a</i> ))</span></p></div><div className="question"><div className="nb"></div><div className="nb">b</div><div className="qtext">APAKAH ANDA MENYUSUN PERHITUNGAN TERSENDIRI ANGSURAN PPh PASAL 25 TAHUN PAJAK BERIKUTNYA?</div><Q s={4} i={2} /></div><div className="opts"><p><Tick s={4} i={6} />Tidak. (Lanjut ke pertanyaan selanjutnya)</p><p><Tick s={4} i={7} />Ya. (Isi Lampiran 4 Bagian A)</p></div><div className="question"><div className="nb"></div><div className="nb">c</div><div className="qtext">APAKAH ANDA MEMBAYAR ANGSURAN PPh PASAL 25 OPPT TAHUN PAJAK BERIKUTNYA?</div><Q s={4} i={3} /></div><div className="opts"><p><Tick s={4} i={8} />Tidak, saya tidak memiliki kewajiban untuk membayar angsuran PPh Pasal 25.</p><p><Tick s={4} i={9} />Ya, angsuran PPh Pasal 25 saya adalah 0,75% dari penghasilan bruto setiap bulan dari masing-masing tempat usaha.</p></div></div><div className="section" data-sec="I">I. PERNYATAAN TRANSAKSI LAINNYA</div><div className="form-body"><div className="line-row"><b>14</b><span style={{"minWidth":"0","flex":"1"}}>HARTA PADA AKHIR TAHUN PAJAK (Isi Lampiran 1 Bagian A, lalu ke pertanyaan selanjutnya)</span><R s={4} i={4} /></div><div className="question"><div className="nb"></div><div className="nb">b</div><div className="qtext">APAKAH ANDA MEMILIKI UTANG PADA AKHIR TAHUN PAJAK?</div><Q s={4} i={4} /></div><div className="opts"><p><Tick s={4} i={10} />Tidak. (Lanjut ke pertanyaan selanjutnya)</p><p><Tick s={4} i={11} />Ya. (Isi Lampiran 1 Bagian B, lalu ke pertanyaan selanjutnya)</p></div><div className="question"><div className="nb"></div><div className="nb">c</div><div className="qtext">APAKAH ANDA MENERIMA PENGHASILAN YANG DIKENAKAN PAJAK PENGHASILAN BERSIFAT FINAL?</div><Q s={4} i={5} /></div><div className="opts"><p><Tick s={4} i={12} />Tidak. (Lanjut ke pertanyaan selanjutnya)</p><p><Tick s={4} i={13} />Ya. (Isi Lampiran 2 Bagian A, lalu ke pertanyaan selanjutnya)</p></div><div className="question"><div className="nb"></div><div className="nb">d</div><div className="qtext">APAKAH ANDA MENERIMA PENGHASILAN YANG TIDAK TERMASUK OBJEK PAJAK?</div><Q s={4} i={6} /></div><div className="opts"><p><Tick s={4} i={14} />Tidak. (Lanjut ke pertanyaan selanjutnya)</p><p><Tick s={4} i={15} />Ya. (Isi Lampiran 2 Bagian B, lalu ke pertanyaan selanjutnya)</p></div><div className="question"><div className="nb"></div><div className="nb">e</div><div className="qtext">APAKAH ANDA MELAPORKAN BIAYA PENYUSUTAN DAN/ATAU AMORTISASI FISKAL?</div><Q s={4} i={7} /></div><div className="opts"><p><Tick s={4} i={16} />Tidak. (Lanjut ke pertanyaan selanjutnya)</p><p><Tick s={4} i={17} />Ya. (Isi Lampiran 3C, lalu ke pertanyaan selanjutnya)</p></div><div className="question"><div className="nb"></div><div className="nb">f</div><div className="qtext">APAKAH ANDA MELAPORKAN BIAYA ENTERTAINMENT, BIAYA PROMOSI, PENGGANTIAN ATAU IMBALAN DALAM BENTUK NATURA DAN/ATAU KENIKMATAN, SERTA PIUTANG YANG NYATA-NYATA TIDAK DAPAT DITAGIH?</div><Q s={4} i={8} /></div><div className="opts"><p><Tick s={4} i={18} />Tidak. (Lanjut ke pertanyaan selanjutnya)</p><p><Tick s={4} i={19} />Ya. (Isi Lampiran 3D, lalu ke pertanyaan selanjutnya)</p></div><div className="question"><div className="nb"></div><div className="nb">g</div><div className="qtext">APAKAH ANDA MENERIMA DIVIDEN DAN/ATAU PENGHASILAN LAIN DARI LUAR NEGERI DAN MELAPORKANNYA SEBAGAI PENGHASILAN TIDAK TERMASUK OBJEK PAJAK?</div><Q s={4} i={9} /></div><div className="opts"><p><Tick s={4} i={20} />Tidak. (Lanjut ke pertanyaan selanjutnya)</p><p><Tick s={4} i={21} />Ya. (Pastikan Anda sudah menyampaikan laporan realisasi investasi secara terpisah)</p></div><div className="line-row"><b className="l">h</b><span style={{"minWidth":"0","flex":"1"}}>KELEBIHAN PPh FINAL ATAS PENGHASILAN DARI USAHA DENGAN PEREDARAN BRUTO TERTENTU YANG DAPAT DIMINTAKAN PENGEMBALIAN.<br /><small>(Silakan mengajukan permohonan pengembalian pajak yang seharusnya tidak terutang secara terpisah)</small></span><R s={4} i={5} /></div></div><div className="section" data-sec="J">J. LAMPIRAN TAMBAHAN</div><div className="form-body"><div style={{"display":"grid","gridTemplateColumns":"6mm 62% 1fr 1fr","alignItems":"center","minHeight":"4.5mm"}}><b style={{"background":"var(--yellow)","textAlign":"center"}}>a</b><span style={{"paddingLeft":"2mm"}}>LAPORAN KEUANGAN/LAPORAN KEUANGAN YANG TELAH DIAUDIT</span><span><Tick s={4} i={22} />TIDAK</span><span><Tick s={4} i={23} />YA</span></div><div style={{"display":"grid","gridTemplateColumns":"6mm 62% 1fr 1fr","alignItems":"center","minHeight":"4.5mm"}}><b style={{"background":"var(--yellow)","textAlign":"center"}}>b</b><span style={{"paddingLeft":"2mm"}}>BUKTI PEMBAYARAN ZAKAT/SUMBANGAN KEAGAMAAN WAJIB</span><span><Tick s={4} i={24} />TIDAK</span><span><Tick s={4} i={25} />YA</span></div><div style={{"display":"grid","gridTemplateColumns":"6mm 62% 1fr 1fr","alignItems":"center","minHeight":"4.5mm"}}><b style={{"background":"var(--yellow)","textAlign":"center"}}>c</b><span style={{"paddingLeft":"2mm"}}>BUKTI PEMOTONGAN/PEMUNGUTAN SEHUBUNGAN DENGAN KREDIT PAJAK LUAR NEGERI</span><span><Tick s={4} i={26} />TIDAK</span><span><Tick s={4} i={27} />YA</span></div><div style={{"display":"grid","gridTemplateColumns":"6mm 62% 1fr 1fr","alignItems":"center","minHeight":"4.5mm"}}><b style={{"background":"var(--yellow)","textAlign":"center"}}>d</b><span style={{"paddingLeft":"2mm"}}>SURAT KUASA KHUSUS</span><span><Tick s={4} i={28} />TIDAK</span><span><Tick s={4} i={29} />YA</span></div><div style={{"display":"grid","gridTemplateColumns":"6mm 62% 1fr 1fr","alignItems":"center","minHeight":"4.5mm"}}><b style={{"background":"var(--yellow)","textAlign":"center"}}>e</b><span style={{"paddingLeft":"2mm"}}>DOKUMEN LAINNYA</span><span><Tick s={4} i={30} />TIDAK</span><span><Tick s={4} i={31} />YA</span></div></div><div className="section" data-sec="K">K. PERNYATAAN</div><div className="kbanner" style={{"background":"var(--yellow)","padding":"2mm 4mm","fontWeight":"bold","display":"flex","gap":"3mm","alignItems":"center","lineHeight":"1.3"}}><Tick s={4} i={32} /><span>DENGAN MENYADARI SEPENUHNYA AKAN SEGALA AKIBATNYA TERMASUK SANKSI-SANKSI SESUAI DENGAN KETENTUAN PERUNDANG-UNDANGAN YANG BERLAKU, SAYA MENYATAKAN BAHWA APA YANG TELAH SAYA BERITAHUKAN DI ATAS BESERTA LAMPIRAN-LAMPIRANNYA ADALAH BENAR, LENGKAP, DAN JELAS.</span></div><div className="form-body" style={{"display":"grid","gridTemplateColumns":"58% 42%","gap":"2mm","marginTop":"2mm"}}><div><div className="line-row">PENANDA TANGAN &nbsp; <Tick s={4} i={33} />WAJIB PAJAK &nbsp; <Tick s={4} i={34} />WAKIL/KUASA</div><div className="line-row">NIK/NPWP &nbsp;<Digits s={4} i={0} cls="digitrow " count={16} /></div><div className="line-row">NAMA LENGKAP &nbsp;<Box s={4} i={3} style={{"width":"65mm"}} /></div></div><div style={{"textAlign":"center"}}>TANGGAL &nbsp;&nbsp; BULAN &nbsp;&nbsp; TAHUN<br /><Digits s={4} i={1} cls="digitrow " count={2} /> &nbsp; <Digits s={4} i={2} cls="digitrow " count={2} /> &nbsp; <Digits s={4} i={3} cls="digitrow " count={4} /><div className="kbox" style={{"border":"1px solid #3775bd","height":"10mm","marginTop":"1mm","paddingTop":"4mm","textAlign":"right"}}>TANDA TANGAN &nbsp;</div></div></div></section>);
}

